mapper.select:
SELECT A.MST_NO AS id, A.TITLE AS title, CONVERT(varchar(10), CONVERT(date, A.START_DATE, 112), 23) AS start, CONVERT(varchar(10), CONVERT(date, A.START_DATE, 112), 23) AS [end] FROM dbo.TWK_SCHEDULE_NEW A WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE}
AND CONVERT(date, A.START_DATE) >= #{start} AND CONVERT(date, A.START_DATE) <= #{end}
UNION SELECT 99999999 AS id, B.NAME + '(' + E.ABSENT_NAME + ')' AS title, CONVERT(varchar(10), CONVERT(date, A.START_DATE, 112), 23) AS start, CONVERT(varchar(10), CONVERT(date, A.END_DATE, 112), 23) AS [end] FROM dbo.TAD_ABSENT AS A LEFT JOIN dbo.TAD_EMP AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO LEFT JOIN dbo.TAD_ABSENT_ITEM AS E ON A.ABSENT_CD = E.ABSENT_CD AND A.OFFICE_CODE = E.OFFICE_CODE WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE}
AND CONVERT(date, A.START_DATE) >= #{start} AND CONVERT(date, A.END_DATE) <= #{end}
ORDER BY id

SELECT
	A.MST_NO			AS MST_NO,
	A.IMPORTANT_YN		AS IMPORTANT_YN,
	A.MY_SCHEDULE		AS MY_SCHEDULE,
	A.TITLE				AS TITLE,
	A.START_DATE		AS START_DATE,
	A.END_DATE			AS END_DATE,
	A.SCH_GBN			AS SCH_GBN,
	B.GBN_NAME      	AS GBN_NAME,
	A.MAIN_DEPT_CD		AS MAIN_DEPT_CD,
	C.DEPT_NAME 		AS MAIN_DEPT_NAME,
	A.STATUS_CD			AS STATUS_CD
FROM dbo.TWK_SCHEDULE_NEW A
LEFT JOIN dbo.TWK_SCHEDULE_GBN AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.SCH_GBN = B.SCH_GBN
LEFT JOIN dbo.THR_DEPT AS C ON A.OFFICE_CODE = C.OFFICE_CODE AND A.MAIN_DEPT_CD = C.DEPT_CD
WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE}

		AND A.START_DATE >= #{START_DATE}


		AND A.END_DATE  <= #{END_DATE}


		AND A.START_DATE >= #{START_DATE}
		AND A.END_DATE  <= #{END_DATE}


		AND A.SCH_GBN = #{SCH_GBN}


		AND A.MAIN_DEPT_CD = #{MAIN_DEPT_CD}


		AND ISNULL(A.IMPORTANT_YN, 'Y') = #{IMPORTANT_YN}


		AND A.STATUS_CD = #{STATUS_CD}


		A.TITLE LIKE '%' + #{TEXT} + '%' OR A.DESCR LIKE '%' + #{TEXT} + '%'

update.if:
UPDATE A SET A.TITLE = U.TITLE, A.IMPORTANT_YN = U.IMPORTANT_YN, A.DESCR = U.DESCR, A.SCH_GBN = U.SCH_GBN, A.MAIN_DEPT_CD = U.MAIN_DEPT_CD FROM dbo.TWK_MONTH_SCHEDULE A JOIN(
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.MST_DATE} AS MST_DATE, #{row.MST_NO} AS MST_NO, #{row.MST_MONTH} AS MST_MONTH, #{row.TITLE} AS TITLE, #{row.IMPORTANT_YN} AS IMPORTANT_YN, #{row.DESCR} AS DESCR, #{row.SCH_GBN} AS SCH_GBN, #{row.MAIN_DEPT_CD} AS MAIN_DEPT_CD
) AS U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.MST_DATE = U.MST_DATE AND A.MST_NO = U.MST_NO AND A.MST_MONTH = U.MST_MONTH

mapper.delete:
DELETE FROM dbo.TWK_MONTH_SCHEDULE WHERE EXISTS ( SELECT 1 FROM (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.MST_DATE} AS MST_DATE, #{row.MST_MONTH} AS MST_MONTH, #{row.MST_NO} AS MST_NO
) AS temp WHERE temp.OFFICE_CODE = TWK_MONTH_SCHEDULE.OFFICE_CODE AND temp.MST_DATE = TWK_MONTH_SCHEDULE.MST_DATE AND temp.MST_MONTH = TWK_MONTH_SCHEDULE.MST_MONTH AND temp.MST_NO = TWK_MONTH_SCHEDULE.MST_NO )

update.if:
UPDATE A SET A.TITLE = U.TITLE FROM dbo.TWK_MONTH_BASIC_JOB A JOIN(
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.MST_DATE} AS MST_DATE, #{row.MST_NO} AS MST_NO, #{row.MST_MONTH} AS MST_MONTH, #{row.TITLE} AS TITLE
) AS U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.MST_DATE = U.MST_DATE AND A.MST_NO = U.MST_NO AND A.MST_MONTH = U.MST_MONTH

mapper.delete:
DELETE FROM dbo.TWK_MONTH_BASIC_JOB WHERE EXISTS ( SELECT 1 FROM (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.MST_DATE} AS MST_DATE, #{row.MST_MONTH} AS MST_MONTH, #{row.MST_NO} AS MST_NO
) AS temp WHERE temp.OFFICE_CODE = TWK_MONTH_BASIC_JOB.OFFICE_CODE AND temp.MST_DATE = TWK_MONTH_BASIC_JOB.MST_DATE AND temp.MST_MONTH = TWK_MONTH_BASIC_JOB.MST_MONTH AND temp.MST_NO = TWK_MONTH_BASIC_JOB.MST_NO )
